const KEY='bookese-occupancy-v1', $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], clone=o=>JSON.parse(JSON.stringify(o)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let automatic=new URLSearchParams(location.search).get('mode')==='automatic',autoExample=new URLSearchParams(location.search).get('sample')==='ab';
let config=initialConfig();try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved)config=normalizeConfig(saved);}catch{}
let draft=clone(config), search={in:'2026-11-10',out:'2026-11-11',adults:5,children:[],rooms:2,market:'Đà Nẵng'},pendingSearch=clone(search),selected=emptySelection(),allocation=[],activeRoom='a',popover=false,guestDraft=null,lastBooking=null,configDirty=false,formError='',checkoutError='',contact={},hideBanner=false,calendarStart='2026-11-10',selectedPlan=null;
let pendingTransfer=null,transferUndo=null;
function emptySelection(){return Object.fromEntries(config.rooms.map(r=>[r.id,0]));}
function customerConfig(){if(!autoExample)return config;const c=clone(config);c.rooms=[{...c.rooms[0],id:'a',name:'A · Awaken Da Nang Hotel',base:2,max:4,adults:4,children:2,beds:1,bedEnabled:true,price:700000,flexPrice:850000,inventory:12},{...c.rooms[1],id:'b',name:'B · alo ha',base:3,max:5,adults:5,children:2,beds:1,bedEnabled:true,price:800000,flexPrice:950000,inventory:1}];c.extraEnabled=true;c.bedIncludesGuest=true;c.adultFee=150000;return c;}
function currentBookingSearch(){return {...search,rooms:allocation.length};}
function bookingValidation(){return validateBooking(allocation,currentBookingSearch(),customerConfig());}
function currentAutoQuote(){return quoteAutomatic(selected,search,customerConfig(),selectedPlan||'standard');}
function modePicker(){return `<div class="customer-mode-picker"><div><span>Phương án khách hàng</span><button class="${!automatic?'active':''}" data-action="set-mode" data-mode="manual">1. Khách điều chỉnh</button><button class="${automatic?'active':''}" data-action="set-mode" data-mode="automatic">2. Hệ thống tự tính</button></div><div><button class="${!autoExample?'active':''}" data-action="auto-sample" data-sample="saved">Cấu hình Extranet</button><button class="${autoExample?'active':''}" data-action="auto-sample" data-sample="ab">Thử ví dụ A/B</button></div></div><div class="auto-mode-description">${automatic?'Chỉ chọn loại phòng và số lượng; phụ thu hiển thị chung cho cả đơn, không gắn với phòng nào.':'Bạn có thể chọn phòng nhận giường phụ hoặc phụ thu bằng nút Đổi phòng; xem thông tin trong Chi tiết khách & giá.'} Hai phương án cùng quy tắc giá: trẻ em dùng suất tiêu chuẩn còn trống; vượt tiêu chuẩn thì dùng giường có sẵn và phụ thu theo tuổi. Giường phụ ưu tiên cho khách tính giá người lớn thêm. Có thể chọn ít hoặc nhiều phòng hơn số tìm kiếm khi đủ chỗ.${autoExample?' <b>Dữ liệu ví dụ riêng: A tiêu chuẩn 2/tối đa 4, B tiêu chuẩn 3/tối đa 5; mỗi phòng tối đa 1 giường phụ. Không thay đổi Extranet.</b>':''}</div>`;}
function changeMode(mode,sample){transferUndo=null;automatic=mode==='automatic';autoExample=sample==='ab';const url=new URL(location.href);url.searchParams.set('mode',automatic?'automatic':'manual');if(autoExample)url.searchParams.set('sample','ab');else url.searchParams.delete('sample');history.replaceState(null,'',url);allocation=[];selected=emptySelection();selectedPlan=null;contact.terms=false;checkoutError='';nav('/customer/hotel');render();}
const paths={house:'<path d="m3 10 9-7 9 7v11h-6v-7H9v7H3z"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4m10-4v4M3 11h18m-13 4h1m6 0h1m-8 3h1"/>',bed:'<path d="M3 18V8m18 10V8M3 15h18M3 10h18v5M6 10V6h5v4m2 0V6h5v4M3 18v3m18-3v3"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',building:'<path d="M5 21V5l14-3v19M3 21h18M9 7v2m6-3v2m-6 4v2m6-3v2m-6 4v3m6-4v4"/>',mail:'<rect x="3" y="5" width="18" height="14" rx="1"/><path d="m3 6 9 7 9-7"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z"/>',chart:'<path d="M4 21V12h3v9m4 0V3h3v18m4 0V8h3v13"/>',wallet:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M16 10h6v6h-6zm-1-5V2H5v3"/>',ticket:'<path d="M3 5h18v5a2 2 0 0 0 0 4v5H3v-5a2 2 0 0 0 0-4zM15 5v3m0 3v2m0 3v3"/>',plane:'<path d="m2 16 8-4-2-9 3-1 5 8 5-1 1 3-6 3-2 7-3 1-1-6-6 2z"/>',pin:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0z"/><circle cx="12" cy="10" r="3"/>',gift:'<path d="M3 9h18v4H3zm2 4v8h14v-8M12 9v12m0-12C2 9 5 0 9 4l3 5c10 0 7-9 3-5z"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-5 6 8 16 8 16S25 11 20 5z"/>',check:'<path d="m4 12 5 5L21 5"/>',menu:'<path d="M3 6h18M3 12h18M3 18h18"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v1"/>',arrow:'<path d="m9 5 7 7-7 7"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',wifi:'<path d="M2 8a16 16 0 0 1 20 0M5 12a11 11 0 0 1 14 0m-11 4a6 6 0 0 1 8 0m-4 4h.01"/>'};
const icon=(name,cls='')=>`<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.building}</svg>`;
const route=()=>location.hash.slice(1)||'/extranet/policy';const nav=url=>{popover=false;location.hash=url;};
const input=(name,value,unit='',extra='')=>`<div class="unit-input ${unit.length>5?'wide':''}"><input type="number" min="0" step="1" data-config="${name}" value="${value}" aria-label="${esc(name)}" ${extra}>${unit?`<span>${unit}</span>`:''}</div>`;
const configInput=(name,value,label,unit='')=>`<label class="field"><span>${label}</span>${input(name,value,unit)}</label>`;
const roomInput=(r,k,label,unit='',extra='')=>`<label class="field"><span>${label}</span><div class="unit-input"><input type="number" min="0" step="1" data-room="${r.id}" data-field="${k}" value="${r[k]}" aria-label="${esc(label+' '+r.name)}" ${extra}>${unit?`<span>${unit}</span>`:''}</div></label>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function modal(title,body,footer=''){popover=false;$('#overlay').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modal-head"><h2>${title}</h2><button class="modal-close" data-action="close-modal" aria-label="Đóng">×</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;$('#overlay .modal-close')?.focus();}
function toolbar(){let admin=route().includes('extranet');return `<div class="proto-bar"><div class="proto-nav"><strong><span class="status-dot"></span>BẢN THỬ NGHIỆM</strong><a class="${admin?'active':''}" href="#/extranet/policy">Extranet</a><a class="${!admin?'active':''}" href="#/customer/home">Bookese khách hàng</a></div><span>Dữ liệu minh họa · Không tạo đơn thật</span><div class="proto-nav"><button data-action="scenarios">Tình huống thử</button><button data-action="rules">Quy tắc & thay đổi</button><button data-action="reset">Đặt lại</button></div></div>`;}
function adminShell(content,title){const page=route().split('/').pop();let items=[['house','Tổng quan'],['building','Quản lý chỗ nghỉ'],['chart','Quản lý thứ hạng'],['heart','Danh sách yêu thích'],['calendar','Quản lý đặt chỗ'],['user','Quản lý khách hàng'],['chart','Quản lý doanh thu'],['star','Quản lý đánh giá'],['building','Quản lý nội dung'],['user','Quản lý tài khoản'],['settings','Quản lý thao tác'],['wallet','Quản lý thanh toán'],['gift','Quản lý xu'],['ticket','Quản lý khuyến mãi'],['wallet','Quản lý thuế'],['pin','Khám phá'],['gift','Quà tặng']];return `<div class="admin"><aside class="admin-sidebar"><a class="admin-logo" href="#/extranet/dashboard"><img src="assets/logo.svg" alt="bookese"></a>${items.map(([ic,t],i)=>`${i===3?'<a class="sideitem sub" href="#/extranet/dashboard"><img src="assets/hotel.jpg" alt=""> Awaken Da Nang Hotel</a>':''}<${i<2?'a':'div'} class="sideitem ${i===1?'active':''}" ${i<2?'href="#/extranet/dashboard"':''}>${icon(ic)}${t}</${i<2?'a':'div'}>`).join('')}</aside><header class="admin-header"><a class="admin-topitem ${page==='dashboard'?'active':''}" href="#/extranet/dashboard">${icon('house')}Trang chủ</a><div class="admin-topitem"><details><summary>${icon('calendar')}Giá & Phòng trống ⌄</summary><div class="dropdown"><a href="#/extranet/calendar">Lịch giá và phòng trống</a><a href="#/extranet/rooms">Loại phòng</a></div></details><span style="visibility:hidden">Giá & Phòng trống</span></div><span class="admin-topitem disabled-nav">${icon('ticket')}Khuyến mãi</span><div class="admin-topitem ${['policy','rooms','capacity'].includes(page)?'active':''}"><details><summary>${icon('building')}Chỗ nghỉ ⌄</summary><div class="dropdown"><a href="#/extranet/rooms">Loại phòng</a><a href="#/extranet/policy">Chính sách trẻ em và giường phụ</a></div></details><span style="visibility:hidden">Chỗ nghỉ</span></div><a class="admin-topitem" href="#/extranet/bookings">${icon('calendar')}Đặt phòng</a><span class="admin-topitem disabled-nav">${icon('mail')}Hộp thư</span><span class="admin-topitem disabled-nav">${icon('star')}Đánh giá</span><span class="admin-topitem disabled-nav">${icon('wallet')}Tài chính</span><span class="admin-topitem disabled-nav">${icon('chart')}Phân tích</span><div class="header-utilities"><span class="flag">🇻🇳</span>${icon('user')}</div></header><main class="admin-main"><div class="admin-title"><h1>${title.toUpperCase()}</h1><div class="breadcrumbs">Chỗ nghỉ &nbsp; / &nbsp; Chính sách &nbsp; / &nbsp; ${title}</div></div>${formError?`<div class="note error draft-error">${esc(formError)}</div>`:''}${content}</main></div>`;}
function adminActions(){return `<div class="admin-actions sticky-bottom"><span class="save-state">${configDirty?'Có thay đổi chưa lưu':'Cấu hình đang áp dụng cho bản thử nghiệm'}</span><button class="btn ghost" data-action="cancel-config">Hủy</button><button class="btn" data-action="save-config">Cập nhật</button></div>`;}
function bedLayout(r,c){const beds=roomBeds(r,c),places=existingExtraPlaces(r,c),invalid=beds>r.max-r.base;return `<div class="bed-layout ${invalid?'invalid':''}"><b>Khả năng bố trí giường · ${r.name}</b><div>${r.base} khách tiêu chuẩn + ${beds} giường phụ + ${places} chỗ thêm dùng giường có sẵn = ${r.base+beds+places} chỗ</div><small>${invalid?'Số giường phụ vượt phần sức chứa còn lại. Vui lòng giảm số giường phụ.':`Chỗ thêm dùng giường có sẵn: ${r.max} − ${r.base} − ${beds} = ${places} (tự tính).`} Tối đa ${r.max} khách, không quá ${r.adults} người lớn và ${r.children} trẻ em. Trẻ dưới mốc giá người lớn được dùng chung giường có sẵn trong các giới hạn này.</small></div>`;}
function adultSurchargePolicy(c){
 const subject=`Người lớn và trẻ từ ${c.adultFrom} tuổi vượt số khách tiêu chuẩn`,fee=`${money(c.adultFee)}/người/đêm`;
 if(!c.extraEnabled)return `${subject}: chỗ nghỉ không cung cấp giường phụ; áp dụng phụ thu ${fee} khi dùng giường có sẵn, trong giới hạn sức chứa của từng phòng.`;
 return `${subject}: <b>áp dụng giường phụ trước</b>, theo số lượng và giá giường phụ của từng loại phòng.<br>Chỉ khi phòng không cung cấp hoặc đã sử dụng hết số giường phụ cho phép, khách thêm còn lại mới áp dụng phụ thu <b>${fee}</b> khi dùng giường có sẵn, nếu vẫn còn sức chứa.<br>Mức phí dùng giường có sẵn không phải là lựa chọn thay thế cho giường phụ khi phòng vẫn còn khả năng bố trí giường phụ.${!c.bedIncludesGuest?`<br>Theo cấu hình hiện tại, giá giường phụ chưa gồm phụ thu người sử dụng: khách dùng giường phụ trả thêm ${fee} ngoài tiền giường.`:''}`;
}
function adminPolicy(){let c=draft;return adminShell(`<div class="admin-card"><h2>Bạn có cho trẻ em dưới 18 tuổi lưu trú tại chỗ nghỉ không?</h2><div class="radio-block"><label><input type="radio" name="allowChildren" data-config="allowChildren" value="true" ${c.allowChildren?'checked':''}>Có</label><label><input type="radio" name="allowChildren" data-config="allowChildren" value="false" ${!c.allowChildren?'checked':''}>Không</label></div></div><div class="admin-card"><h2>Thiết lập giá và giới hạn tuổi của Bạn cho Trẻ em</h2>${!c.allowChildren?'<div class="note warning">Chỗ nghỉ không nhận khách dưới 18 tuổi. Chính sách giá bên dưới được giữ lại để dùng khi bật lại.</div>':''}<div class="age-row"><div class="field"><span>Tuổi</span><div class="age-inputs"><select aria-label="Khoảng tuổi miễn phí" disabled><option>Dưới</option></select>${input('childFreeBelow',c.childFreeBelow,'Tuổi')}</div></div><label class="field"><span>Giá khi dùng giường có sẵn</span><div class="unit-input"><input value="0" disabled aria-label="Giá trẻ nhỏ"><span>VNĐ</span></div></label></div><div class="age-row"><div class="field"><span>Tuổi</span><div class="age-inputs"><select disabled aria-label="Khoảng tuổi có phụ thu"><option>Từ</option></select><div class="age-range"><input value="${c.childFreeBelow}" disabled aria-label="Tuổi bắt đầu phụ thu"><span>đến</span><input value="${childAgeUpper(c)}" disabled aria-label="Tuổi kết thúc phụ thu"></div></div><small class="muted">Từ ${c.childFreeBelow} đến dưới ${c.adultFrom} tuổi (cận trên hiển thị ${childAgeUpper(c)}).</small></div>${configInput('childFee',c.childFee,'Giá khi dùng giường có sẵn','VNĐ')}</div><div class="age-row"><div class="field"><span>Tuổi <span class="tag">Làm rõ mốc tuổi</span></span><div class="age-inputs"><select disabled aria-label="Tính giá người lớn"><option>Từ</option></select>${input('adultFrom',c.adultFrom,'Tuổi','max="18"')}</div><small class="muted">Bao gồm trẻ đúng ${c.adultFrom} tuổi. Giữ nguyên tuổi thực của trẻ.</small></div><label class="field"><span>Giá khi dùng giường có sẵn</span>${input('adultFee',c.adultFee,'VNĐ')}<small class="muted">Áp dụng cho người lớn và trẻ từ ${c.adultFrom} tuổi tính giá người lớn. Không bao gồm giường phụ.</small><small class="muted">Số người được ở thêm do từng loại phòng quy định. Vẫn áp dụng mức phí này khi không cung cấp giường phụ.</small></label></div><hr class="divider"><div class="policy-summary"><h3>Tóm tắt chính sách</h3><p class="small">Trẻ dùng suất tiêu chuẩn còn trống không phụ thu; phí trẻ em bên dưới chỉ tính khi vượt số khách tiêu chuẩn trong phòng.</p><ul class="small"><li>Trẻ dưới ${c.childFreeBelow} tuổi miễn phụ thu khi dùng giường có sẵn.</li><li>Trẻ ${c.childFreeBelow}–${childAgeUpper(c)} tuổi: ${money(c.childFee)}/trẻ/đêm khi dùng giường có sẵn.</li><li>${adultSurchargePolicy(c)}</li></ul></div></div><div class="admin-card"><h2>Bạn có muốn thêm giường phụ không?</h2><div class="radio-block"><label><input type="radio" name="extraEnabled" data-config="extraEnabled" value="true" ${c.extraEnabled?'checked':''}>Có</label><label><input type="radio" name="extraEnabled" data-config="extraEnabled" value="false" ${!c.extraEnabled?'checked':''}>Không</label></div>${!c.extraEnabled?`<p class="small muted section-space">Không cung cấp giường phụ. Chỗ thêm dùng giường có sẵn = Sức chứa tối đa − Số khách tiêu chuẩn.</p>${c.rooms.map(r=>bedLayout(r,c)).join('')}`:''}</div>${c.extraEnabled?`<div class="admin-card"><h2 style="margin-bottom:4px">Chính sách giường phụ</h2><p class="muted">Cài đặt giường phụ theo từng loại phòng</p><div class="table-scroll"><table class="admin-table"><thead><tr><th></th><th>Phòng</th><th>Số lượng giường phụ tối đa/phòng</th><th>Giá mỗi giường/đêm</th></tr></thead><tbody>${c.rooms.map(r=>`<tr><td><input type="checkbox" data-room="${r.id}" data-field="bedEnabled" aria-label="Giường phụ ${r.name}" ${r.bedEnabled?'checked':''}></td><td>${r.name}</td><td>${roomInput(r,'beds','Số giường phụ', '',r.bedEnabled?'max="'+Math.max(0,r.max-r.base)+'"':'disabled')}</td><td class="price-field">${roomInput(r,'bedPrice','Giá giường phụ','VNĐ',r.bedEnabled?'':'disabled')}</td></tr><tr class="bed-layout-row"><td></td><td colspan="3">${bedLayout(r,c)}</td></tr>`).join('')}</tbody></table></div><div class="section-space"><label class="check"><input type="checkbox" data-config="bedIncludesGuest" ${c.bedIncludesGuest?'checked':''}>Giá giường phụ đã bao gồm phụ thu người sử dụng giường <span class="tag">Mới</span></label><p class="small muted" style="padding-left:24px;margin:7px 0">${c.bedIncludesGuest?'Khách dùng giường phụ chỉ trả giá giường; không cộng trùng phụ thu người lớn hoặc trẻ em của khách đó.':'Khách dùng giường phụ trả phí giường cộng phụ thu lưu trú áp dụng cho khách đó.'}</p></div><div class="note section-space"><b>Giường phụ luôn được ưu tiên áp dụng trước.</b><br>Khách tính giá người lớn vượt tiêu chuẩn được áp dụng giường phụ đến giới hạn đã cài đặt, sau đó phụ thu giường có sẵn. Trẻ dưới mốc giá người lớn dùng giường có sẵn; chỉ phụ thu theo tuổi khi hết suất tiêu chuẩn. Quy tắc áp dụng cho cả hai phương án khách hàng.</div></div>`:''}<div class="admin-card"><div class="row between wrap"><div><h3>Giới hạn khách theo từng loại phòng</h3><p class="small muted" style="margin:0">Thiết lập số khách tiêu chuẩn và giới hạn sức chứa. Chỗ thêm dùng giường có sẵn được tự tính tại chính sách giường phụ.</p></div><a href="#/extranet/rooms" class="btn secondary">Đi đến Loại phòng →</a></div></div>${adminActions()}`,'Chính sách trẻ em và giường phụ');}
function adminRooms(){return adminShell(`<div class="row between section-space"><p class="muted">Các loại phòng tại Awaken Da Nang Hotel</p><a class="linkbtn" href="#/extranet/policy">Chính sách trẻ em và giường phụ →</a></div>${draft.rooms.map(r=>`<div class="admin-card room-list"><img src="assets/room.jpg" alt="${r.name}"><div><h3>${r.name}</h3><p>Khách tiêu chuẩn: <b>${r.base}</b> &nbsp; · &nbsp; Sức chứa tối đa: <b>${r.max}</b></p><p>Tối đa ${r.adults} người lớn · ${r.children} trẻ em · ${roomBeds(r,draft)} giường phụ</p><p class="muted">${r.inventory} phòng để bán · Giá cơ bản ${money(r.price)}/đêm</p></div><button class="btn small" data-action="edit-room" data-id="${r.id}">Chỉnh sửa</button></div>`).join('')}`,'Loại phòng');}
function adminCapacity(){const r=draft.rooms.find(r=>r.id===activeRoom);const fields=[['base','Số khách tiêu chuẩn','Giá cơ bản bao gồm người lớn và trẻ em trong số khách tiêu chuẩn. Ưu tiên suất cho khách tính giá người lớn; trẻ em dùng suất còn trống không phụ thu.'],['max','Sức chứa tối đa','Giới hạn tổng khách trong phòng, đã bao gồm khách dùng giường phụ.'],['adults','Số người lớn tối đa','Giới hạn người lớn thực tế, không phụ thuộc phương án giường.'],['children','Số trẻ em tối đa','Bao gồm trẻ miễn phí và trẻ áp dụng giá người lớn.']];return adminShell(`<div class="room-title-picker"><a href="#/extranet/rooms">← Loại phòng</a><select aria-label="Chọn loại phòng" id="active-room">${draft.rooms.map(x=>`<option value="${x.id}" ${x.id===r.id?'selected':''}>${x.name}</option>`).join('')}</select></div><div class="admin-subnav"><a class="active" href="#/extranet/capacity">Thông tin phòng & sức chứa</a><a href="#/extranet/policy">Chính sách trẻ em & giường phụ</a><a href="#/extranet/calendar">Giá & phòng trống</a></div><div class="admin-card"><h2>Sức chứa</h2>${fields.map(([k,label,hint])=>`<div class="capacity-row"><div><h3>${label}<span class="red">*</span></h3><p>${hint}</p></div><input type="number" min="${['base','max','adults'].includes(k)?1:0}" step="1" data-room="${r.id}" data-field="${k}" value="${r[k]}" aria-label="${label}"></div>`).join('')}<div class="row between section-space"><span class="small muted">Giường phụ tối đa: ${roomBeds(r,draft)} · ${money(r.bedPrice)}/giường/đêm</span><a href="#/extranet/policy">Chỉnh chính sách giường phụ →</a></div></div>${adminActions()}`,'Chỉnh sửa loại phòng');}
function dateAdd(d,n){let date=new Date(d+'T00:00:00Z');date.setUTCDate(date.getUTCDate()+n);return date.toISOString().slice(0,10);}
function adminCalendar(){const dates=Array.from({length:7},(_,i)=>dateAdd(calendarStart,i));return adminShell(`<div class="admin-card calendar-controls"><span>Tìm theo Phòng</span><select id="calendar-room" aria-label="Phòng trong lịch"><option value="all">Tất cả phòng</option>${draft.rooms.map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select><span>Chọn thời gian xem</span><input id="calendar-start" type="date" value="${calendarStart}"></div><div class="admin-card"><p class="small muted">Giá và inventory mẫu áp dụng giống nhau cho các ngày trong bản thử nghiệm. Chỉnh giá cơ bản / số phòng của loại phòng để thử lại kết quả tìm kiếm.</p><div class="calendar-wrap"><table class="calendar-table"><thead><tr><th></th>${dates.map(d=>`<th>${new Date(d+'T00:00:00Z').toLocaleDateString('vi-VN',{weekday:'short',timeZone:'UTC'})}<br>${d.slice(8)}/${d.slice(5,7)}<br>2026</th>`).join('')}</tr></thead><tbody>${draft.rooms.map(r=>`<tr class="calendar-room" data-calendar-id="${r.id}"><td class="room-head" colspan="8">${r.name.toUpperCase()}</td></tr><tr data-calendar-id="${r.id}"><td>Trạng thái phòng</td>${dates.map(()=>`<td><span class="pill">${r.inventory?'Đặt được':'Hết phòng'}</span></td>`).join('')}</tr><tr data-calendar-id="${r.id}"><td>Phòng để bán</td>${dates.map((d,i)=>`<td>${i===0?`<input type="number" data-room="${r.id}" data-field="inventory" min="0" value="${r.inventory}" aria-label="Inventory ${r.name}">`:r.inventory}</td>`).join('')}</tr><tr data-calendar-id="${r.id}"><td>Giá cơ bản <small class="muted">(${r.base} khách) · Tiết kiệm</small></td>${dates.map((d,i)=>`<td>${i===0?`<input type="number" data-room="${r.id}" data-field="price" min="0" value="${r.price}" aria-label="Giá cơ bản ${r.name}">`:money(r.price)}</td>`).join('')}</tr><tr data-calendar-id="${r.id}"><td>Gói Linh hoạt <small class="muted">(${r.base} khách)</small></td>${dates.map((d,i)=>`<td>${i===0?`<input type="number" data-room="${r.id}" data-field="flexPrice" min="0" value="${r.flexPrice}" aria-label="Giá linh hoạt ${r.name}">`:money(r.flexPrice)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>${adminActions()}`,'Lịch');}
function adminDashboard(){return adminShell(`<div class="row between section-space"><b>1772765796 - Awaken Da Nang Hotel &nbsp;<span class="pill">Mở/ Có thể đặt phòng</span></b></div><div class="dashboard-grid"><div><div class="admin-card"><h3>Tổng quan đặt phòng hôm nay</h3><div class="mini-tabs"><span class="selected">Khách đến (0)</span><span>Khách đi (0)</span><span>Đặt phòng mới (${lastBooking?1:0})</span></div><div class="empty muted">Bạn không có khách đến trong hôm nay</div></div><div class="admin-card"><h3>Thiết lập phòng và chính sách</h3><p class="muted">Cập nhật sức chứa, phụ thu và giường phụ cho từng loại phòng.</p><div class="row wrap"><a href="#/extranet/rooms" class="btn secondary">Loại phòng</a><a href="#/extranet/policy" class="btn">Chính sách trẻ em & giường phụ</a><a href="#/extranet/calendar" class="btn secondary">Lịch giá</a></div></div><div class="admin-card"><h3>Các đánh giá gần đây</h3>${[['4','zxv'],['7,5','Phòng đẹp, chất lượng'],['10','test comment']].map(([score,txt])=>`<div class="review-line"><b>${score}</b><span>Khách lưu trú</span><span>${txt}</span><span class="spacer"></span><small class="muted">19/06/2026</small></div>`).join('')}</div></div><aside class="dashboard-mini"><img src="assets/hotel.jpg" alt="Awaken Da Nang Hotel"><h2>Awaken Da Nang Hotel</h2><div class="stars">★★★★★</div><p>10 Chemin de Montpellier, Phường An Hải Bắc, Quận Sơn Trà, Đà Nẵng</p><small>Điểm trung bình đánh giá: <b>7.8/10</b></small></aside></div>`,'Trang chủ');}
function customerHeader(){return `${!hideBanner?'<div class="customer-warning">⚠ &nbsp; Website đang hoạt động ở chế độ thử nghiệm, đang thực hiện đăng ký với Bộ Công Thương <button data-action="hide-banner" aria-label="Đóng thông báo">×</button></div>':''}<header class="customer-header"><a href="#/customer/home"><img class="logo" src="assets/logo.svg" alt="bookese"></a><nav class="customer-menu"><a class="selected" href="#/customer/home">${icon('house')}Lưu trú</a><a class="disabled-nav">${icon('plane')}Vé máy bay</a><a class="disabled-nav">${icon('ticket')}Trải nghiệm</a><a class="disabled-nav">${icon('pin')}Khám phá</a><a class="disabled-nav">${icon('gift')}Đổi quà</a></nav><span class="spacer"></span><div class="row"><b>VND</b><b>VN</b>${icon('mail')}<span class="avatar"></span></div></header>`;}
function footer(){return `<footer class="footer"><div><img src="assets/logo.svg" alt="bookese"><p>CÔNG TY TNHH TM DV BOOKESE<br>Du lịch không giới hạn</p></div><div>Dịch vụ của Bookese<p>Lưu trú · Khám phá · Hạng thành viên</p></div><div>Liên hệ<p>info@bookese.com<br>© 2026 Bookese.</p></div></footer>`;}
const summary=s=>`${s.adults} người lớn · ${s.children.length} Trẻ em · ${s.rooms} phòng`;
function guestPopover(){const s=guestDraft||pendingSearch;return `<div class="guest-pop" role="dialog" aria-label="Phòng và người"><div class="counter-row"><div><b>Người lớn</b><small class="muted" style="display:block">Từ 18 tuổi</small></div>${counter('adults',s.adults,1,24)}</div><div class="counter-row"><div><b>Trẻ em</b><small class="muted" style="display:block">0–17 tuổi</small></div>${counter('children',s.children.length,0,8)}</div>${s.children.length?`<p class="small">Tuổi trẻ em vào ngày nhận phòng</p><div class="child-ages">${s.children.map((age,i)=>`<label class="field"><span>Trẻ ${i+1}</span><select data-child-age="${i}">${Array.from({length:18},(_,n)=>`<option value="${n}" ${n===age?'selected':''}>${n} tuổi</option>`).join('')}</select></label>`).join('')}</div>`:''}<div class="counter-row"><b>Phòng</b>${counter('rooms',s.rooms,1,6)}</div><button class="btn secondary" data-action="apply-guests">Xong</button></div>`;}
function counter(k,n,min,max){return `<div class="counter"><button data-action="counter" data-key="${k}" data-step="-1" aria-label="Giảm ${k}" ${n<=min?'disabled':''}>−</button><strong>${n}</strong><button data-action="counter" data-key="${k}" data-step="1" aria-label="Tăng ${k}" ${n>=max?'disabled':''}>+</button></div>`;}
function searchBar(kind='full'){const s=pendingSearch;return `<div class="search-bar" data-search-kind="${kind}">${kind==='availability'?'':`<div class="search-part">${icon('pin')}<input list="destinations" aria-label="Điểm đến" value="${esc(s.market)}" data-search="market"><datalist id="destinations"><option value="Đà Nẵng"></datalist></div>`}<div class="search-part"><label class="main-search-label">${kind==='availability'?'Ngày Nhận & Trả phòng':'Ngày nhận & trả phòng'}</label><button class="date-display" data-action="edit-dates">${icon('calendar')}<span>${formatDate(s.in)} — ${formatDate(s.out)}</span></button></div><div class="search-part"><label class="main-search-label">Phòng & Người</label><div class="row">${icon('user')}<button data-action="toggle-guests">${summary(s)} &nbsp;⌄</button></div>${popover?guestPopover():''}</div><button class="btn" data-action="search" data-target="${kind==='availability'?'hotel':'results'}">Tìm${kind==='side'?' kiếm':''}</button></div>`;}
function customerShell(content,{band=false}={}){return `<div class="customer ${route().endsWith('/checkout')?'checkout-customer':''}">${customerHeader()}${modePicker()}${band?`<div class="search-band">${searchBar()}</div>`:''}${content}${footer()}</div>`;}
function homePage(){return customerShell(`<main class="customer-main home-main"><section class="home-hero"><h1>Dịch vụ chọn lọc, ưu đãi đa dạng</h1><div class="home-search">${searchBar()}</div></section><section class="home-section"><h2>Phiếu Giảm Giá Độc Quyền</h2><div class="voucher-grid">${[['20%','test voucher public'],['10%','Welcome 100%'],['10%','Welcome 10%']].map(([p,t])=>`<div class="voucher"><strong>${p}<small>Giảm đến</small></strong><div><b>${t}</b><p>Ưu đãi dành cho bạn</p><span>Chỉ hiển thị tham khảo</span></div>${icon('ticket')}</div>`).join('')}</div></section><section class="home-section"><h2>Tìm Kiếm Gần Đây</h2><div class="recent-grid">${[0,1,2].map((_,i)=>`<button class="recent-search" data-action="preset" data-preset="${i===2?'family':'five-two'}"><img src="assets/danang.webp" alt="Đà Nẵng"><span><b>Đà Nẵng</b><small>10 tháng 11 — 11 tháng 11</small><small>${i===2?'4 người lớn · 2 trẻ em · 2 phòng':'5 người lớn · 2 phòng'}</small></span></button>`).join('')}</div></section><section class="home-section"><h2>Chỗ Nghỉ Yêu Thích</h2><div class="favorite-grid">${[['mercure.webp','Mercure Danang French Village Bana Hills','Khách sạn'],['havana.webp','Havana Nha Trang Hotel','Khách sạn'],['sandy.webp','Sandy Beach Non Nuoc Resort','Resort'],['hotel.jpg','Awaken Da Nang Hotel','Khách sạn']].map(([im,t,k],i)=>`<${i===3?'a href="#/customer/hotel"':'article'} class="favorite-card"><div class="favorite-photo"><img src="assets/${im}" alt="${t}"><span>Yêu thích</span></div><div class="favorite-body"><small>${k}</small><span class="stars"> ★★★★★</span><h3>${t}</h3><p class="small muted">${i===1?'Nha Trang':'Đà Nẵng'}, Việt Nam</p>${i===3?'<span class="blue small">Xem phòng & phụ thu →</span>':'<span class="small muted">Chỗ nghỉ tham khảo</span>'}</div></${i===3?'a':'article'}>`).join('')}</div></section></main>`);}
function available(){return search.market.toLocaleLowerCase('vi').includes('đà nẵng')?automaticRecommendations(search,customerConfig()):[];}
function resultsPage(){const recs=available(),best=recs[0];return customerShell(`<main class="customer-main"><div class="crumb"><a href="#/customer/home">Trang chủ</a> › <a href="#/customer/results">${esc(search.market)}</a> › Kết quả tìm kiếm</div><div class="search-layout"><aside class="search-side"><h3>Bạn muốn đến đâu?</h3>${searchBar('side')}</aside><section><div class="row between"><h1>${esc(search.market)}: ${best?'1':'0'} chỗ nghỉ</h1><small class="muted">Sắp xếp theo Lựa chọn hàng đầu</small></div>${best?`<article class="result-card"><img src="assets/hotel.jpg" alt="Awaken Da Nang Hotel"><div><span class="minibadge">Khách sạn</span> <span class="stars">★★★★★</span><h2>Awaken Da Nang Hotel</h2><p class="muted">Đà Nẵng, Việt Nam</p><div class="desc">♧ Lễ tân 24 giờ &nbsp; · &nbsp; Wifi miễn phí<br>Spa & chăm sóc sức khỏe</div><div class="result-plan"><b>${planLabel(best)}</b><p>${planGuests(best)}${best.rooms.length!==search.rooms?' · '+best.rooms.length+' phòng đủ chỗ (bạn tìm '+search.rooms+' phòng)':''}</p><span class="green">✓ Phù hợp cho toàn bộ ${search.adults+search.children.length} khách</span><p><b>Gói ${ratePlan(best.ratePlanId).name}</b><br>✓ ${ratePlan(best.ratePlanId).meals}<br>${ratePlan(best.ratePlanId).cancellation}</p></div></div><div class="result-price"><div class="score"><div>Ổn<small class="muted" style="display:block">5 đánh giá</small></div><strong>7,8</strong></div><small>${nights(search)} đêm, ${best.rooms.length} phòng<br>${search.adults} người lớn${search.children.length?' · '+search.children.length+' trẻ em':''}</small><small class="best-rate-label">${search.rooms===1?'Phòng phù hợp sức chứa':'Tổng giá thấp nhất cho nhóm'}</small><div class="price">${money(best.total)}</div><div class="green small">Hoàn xu +${new Intl.NumberFormat('vi-VN').format(Math.floor(best.total*.02))}</div><p class="small">Đã bao gồm phụ thu, thuế và phí</p><a class="btn" href="#/customer/hotel">Xem phòng &nbsp; ›</a></div></article>`:`<div class="empty"><h2>Không tìm thấy phương án phù hợp</h2><p class="muted">${search.rooms===1&&search.adults>5?'Các loại phòng hiện tại nhận tối đa 5 người lớn/phòng.':'Không có tổ hợp phòng đáp ứng đủ nhóm khách và điều kiện đã chọn.'}</p>${search.rooms===1?'<button class="btn" data-action="try-two">Tìm với 2 phòng</button>':''}<p class="small muted">Đề xuất xét từ 1 đến ${search.rooms} phòng và luôn phải đủ toàn bộ khách.</p><a href="#/customer/hotel">Xem giới hạn từng loại phòng →</a></div>`}</section></div></main>`);}
function planLabel(rec){const config=customerConfig();return Object.entries(rec.counts).filter(([id,n])=>n).map(([id,n])=>n+' × '+config.rooms.find(r=>r.id===id).name).join(' + ');}
function planGuests(rec){if(automatic){const groups=automaticSummary(rec.allocation,{...search,rooms:rec.rooms.length},customerConfig());return bookingFees(groups).map(f=>feeText(f)).join(' · ')||'Không phát sinh phụ thu';}const gs=guestList(search);return rec.allocation.map((a,i)=>{const group=gs.filter(g=>a.guestIds.includes(g.id));return 'Phòng '+(i+1)+': '+group.filter(g=>g.adult).length+' người lớn'+(group.some(g=>!g.adult)?' + '+group.filter(g=>!g.adult).length+' trẻ em':'')+(a.bedIds.length?' · '+a.bedIds.length+' giường phụ':'');}).join(' &nbsp; / &nbsp; ');}
function recommendCard(rec,index){return `<div class="recommendation compact-rec"><div><h3>${search.rooms===1?'Phòng phù hợp với nhóm của bạn':'Tổng giá thấp nhất cho nhóm'} · ${planLabel(rec)}</h3><p>Gói ${ratePlan(rec.ratePlanId).name} · ${planGuests(rec)}${rec.rooms.length!==search.rooms?' · '+rec.rooms.length+' phòng đủ chỗ (bạn tìm '+search.rooms+' phòng)':''}</p></div><div class="rec-price"><small>${rec.rooms.length} phòng · ${nights(search)} đêm · gồm phụ thu</small><strong>${money(rec.total)}</strong></div><button class="btn small" data-action="choose-rec" data-index="${index}">Chọn đề xuất</button></div>`;}

function hotelPage(){const recs=available();return customerShell(`<main class="customer-main"><div class="crumb"><a href="#/customer/home">Trang chủ</a> › <a href="#/customer/results">Đà Nẵng</a> › Awaken Da Nang Hotel</div><nav class="hotel-tabs"><a href="#/customer/hotel" class="active">Tổng quan</a><a href="#/customer/hotel" data-action="scroll-rooms">Thông tin & giá</a><a href="#/customer/hotel" data-action="hotel-info">Vị trí</a><a href="#/customer/hotel" data-action="hotel-info">Tiện ích & Dịch vụ</a><a href="#/customer/hotel" data-action="scroll-policy">Các chính sách</a><a href="#/customer/hotel" data-action="hotel-info">Đánh giá</a></nav><div class="gallery"><img class="main-photo" src="assets/hotel.jpg" alt="Awaken Da Nang Hotel"><span class="fav">Yêu thích</span><img src="assets/room.jpg" alt="Phòng nghỉ hướng biển"><img src="assets/pool.jpg" alt="Hồ bơi khách sạn"></div><div class="hotel-intro"><div><span class="minibadge">Khách sạn</span> <span class="stars">★★★★★</span><h1>Awaken Da Nang Hotel</h1><p class="small">♧ 10 Chemin de Montpellier, Đà Nẵng · <a href="#/customer/hotel" data-action="hotel-info">Xem trên bản đồ</a></p><p class="hotel-description">Nằm ở Đà Nẵng, cách Bãi biển Mỹ Khê 8 phút đi bộ, Awaken Da Nang Hotel cung cấp chỗ nghỉ có trung tâm thể dục, chỗ đậu xe riêng miễn phí, sân hiên và nhà hàng. Mỗi phòng tại khách sạn 5 sao này đều nhìn ra biển, đồng thời khách có thể sử dụng hồ bơi trong nhà.</p><div class="facilities"><span>♧ Nhà hàng</span><span>♧ Hỗ trợ tiền sảnh</span><span>♧ Nhận phòng sớm</span><span>♧ Wifi miễn phí</span><span>♧ Quầy bar</span></div></div><div class="score" style="align-self:start"><strong>7,8</strong><div>Tốt<small class="muted" style="display:block">5 Đánh giá</small></div></div></div><section class="availability" id="availability"><h2>Phòng trống</h2>${searchBar('availability')}${!recs.length?`<div class="note warning">Không có phương án đáp ứng ${summary(search)}. ${search.adults>5&&search.rooms===1?'Các loại phòng hiện tại nhận tối đa 5 người lớn trong một phòng.':''} ${search.rooms===1?'<button class="linkbtn" data-action="try-two">Thử 2 phòng →</button>':''}</div>`:recs.slice(0,1).map(recommendCard).join('')}${!automatic?transferNotice():''}<div class="table-scroll">${automatic?automaticTable({config:customerConfig(),search,selected,selectedPlan,quote:currentAutoQuote(),recs}):roomTable(recs)}</div></section>${customerPolicy()}</main>`,{band:false});}
function roomTable(recs){const config=customerConfig();
 const check=allocation.length?bookingValidation():null;
 const chosenCount=Object.values(selected).reduce((a,b)=>a+b,0),preview=check?null:currentAutoQuote();
 const groups=config.rooms.map(r=>({r,plans:ratePlans.filter(p=>Number.isFinite(ratePrice(r,p.id)))}));
 const rowCount=groups.reduce((n,{r,plans})=>n+Math.max(1,plans.length),0);
 const summaryCell=`<td rowspan="${rowCount}" class="summary-cell"><div class="summary-sticky"><p class="small">Đã chọn ${chosenCount} phòng · ${nights(search)} đêm</p>${selectedPlan?`<span class="pill">Gói ${ratePlan(selectedPlan).name}</span>`:''}${check?`<div class="room-price section-space">${money(check.total)}</div><p class="tax-note">Đã gồm phụ thu, thuế và phí</p>`:preview?.allocation.length?`<p class="small">Tạm tính cho ${preview.covered}/${guestList(search).length} khách</p><div class="room-price">${money(preview.total)}</div><p class="small muted">Chưa phải giá cho toàn bộ đoàn</p>`:'<p class="muted small section-space">Chọn phòng để xem tổng giá cho cả nhóm</p>'}<button class="btn" data-action="checkout" ${check?.valid?'':'disabled'}>Tôi sẽ đặt</button><p class="small ${check?.valid?'green':'muted'}">${check?.valid?'✓ Đủ '+guestList(search).length+' khách':check?'Kiểm tra số khách trong từng phòng':chosenCount?preview.error||'Còn '+preview.missing+' khách chưa có chỗ. Thêm hoặc đổi phòng.':'Chọn số lượng phòng'}</p>${check&&!check.valid?`<p class="small red">${[...new Set(check.errors)].map(esc).join('<br>')}</p>`:''}${check?.valid&&chosenCount!==search.rooms?`<p class="tax-note">Bạn tìm ${search.rooms} phòng; sẽ đặt ${chosenCount} phòng đủ chỗ cho cả nhóm.</p>`:''}<p class="tax-note">Các phòng trong cùng đơn dùng một gói giá. Giường phụ ưu tiên cho khách tính giá người lớn thêm; trẻ nhỏ dùng giường có sẵn.</p></div></td>`;
 return `<table class="room-table"><colgroup><col style="width:23%"><col style="width:9%"><col style="width:18%"><col style="width:26%"><col style="width:7%"><col style="width:17%"></colgroup><thead><tr><th>Loại phòng</th><th>Sức chứa</th><th>Giá 1 phòng / ${nights(search)||1} đêm</th><th>Lựa chọn của bạn</th><th>Số phòng</th><th>Tổng tiền</th></tr></thead><tbody>${groups.map(({r,plans},roomIndex)=>{
  const roomRows=plans.length?plans:[ratePlans[0]];
  return roomRows.map((p,pi)=>{
   const viable=r.inventory>0&&Number.isFinite(ratePrice(r,p.id)),locked=chosenCount>0&&selectedPlan!==p.id;
   const indices=allocation.map((a,i)=>a.roomId===r.id&&a.ratePlanId===p.id?i:-1).filter(i=>i>=0);
   return `<tr class="rate-row ${indices.length?'chosen-rate':''}">${pi===0?`<td rowspan="${roomRows.length}"><button class="room-name linkbtn" data-action="room-details" data-id="${r.id}">${r.name}</button><div class="room-info">${icon('bed')} ${r.id==='d'?'2 giường đôi · Phòng gia đình':'Giường đôi / giường đơn'}<br>Wifi miễn phí · Điều hòa<br>Phòng tắm riêng</div><button class="linkbtn small section-space" data-action="room-details" data-id="${r.id}">Xem thông tin phòng</button><p class="small muted">Còn ${r.inventory} phòng<br>Dùng chung cho các gói giá</p></td><td rowspan="${roomRows.length}"><div class="user-icons">${icon('user')} × ${r.adults}</div><div class="capacity-hint">Tối đa ${r.max} khách<br>${r.adults} người lớn<br>${r.children} trẻ em<br>≤ ${roomBeds(r,config)} giường phụ</div></td>`:''}<td>${viable?`<div class="room-price">${money(ratePrice(r,p.id)*nights(search))}</div><small class="muted">${r.base} khách, gồm người lớn và trẻ em</small><p class="price-small">Chưa cộng phụ thu khách thêm</p>${indices.map(i=>`<div class="selected-room-price">Phòng ${i+1}: <b>${money(check.quotes[i].total)}</b><small>Đã gồm phụ thu</small></div>`).join('')}`:`<p class="red small">${r.inventory?'Không phù hợp nhóm khách đã chọn':'Hết phòng trong ngày đã chọn'}</p>`}</td><td><strong class="rate-name">Gói ${p.name}</strong><p class="rate-policy ${p.id==='flex'?'green':'blue'}">${p.cancellation}</p><p class="rate-policy">✓ ${p.meals}<br>${p.payment}</p>${locked&&viable?`<button class="linkbtn small" data-action="switch-plan" data-plan="${p.id}">Đổi cả đơn sang gói ${p.name} →</button>`:''}${indices.length?`<div class="inline-room-summary">${indices.map(i=>roomGuestSummary(allocation[i],i)+serviceControls(i)).join('')}<button class="linkbtn small" data-action="guest-price-details" data-id="${r.id}">Chi tiết khách & giá</button></div>`:''}</td><td><select data-quantity="${r.id}" data-plan="${p.id}" aria-label="Số phòng ${r.name} · ${p.name}" ${!viable||locked?'disabled':''}>${Array.from({length:Math.min(r.inventory,6,search.adults)+1},(_,n)=>`<option value="${n}" ${selectedPlan===p.id&&(selected[r.id]||0)===n?'selected':''}>${n}</option>`).join('')}</select></td>${roomIndex===0&&pi===0?summaryCell:''}</tr>`;
  }).join('');
 }).join('')}</tbody></table>`;
}

function priceLines(q){return `<div class="price-lines">${q.lines.map(l=>`<div><span>${esc(l.label)}</span><span class="nowrap">${money(l.amount)}</span></div>`).join('')}<div class="total"><span>Tổng phòng</span><span>${money(q.total)}</span></div></div>`;}
function roomGuestSummary(row,i){const gs=guestList(search).filter(g=>row.guestIds.includes(g.id)),adults=gs.filter(g=>g.adult).length,kids=gs.filter(g=>!g.adult);return `<div class="room-occupancy-line"><b>Phòng ${i+1}:</b> ${adults} người lớn${kids.length?' + '+kids.length+' trẻ ('+kids.map(g=>g.age).join(', ')+' tuổi)':''}<small>${row.bedIds.length?row.bedIds.length+' giường phụ':'Dùng giường có sẵn'}</small></div>`;}
function roomLabel(i){return 'Phòng '+(i+1)+' · '+customerConfig().rooms.find(r=>r.id===allocation[i].roomId).name;}
function serviceControls(i){const services=roomServices(allocation,currentBookingSearch(),customerConfig(),i);return `<div class="service-controls">${services.length?services.map(x=>`<div class="service-control"><span><b>${esc(x.label)}</b><small>${money(x.amount/nights(search))} / đêm</small></span><button class="linkbtn" data-action="move-service" data-source="${i}" data-guest="${x.guestId}" data-kind="${x.kind}" aria-label="Đổi phòng cho ${esc(x.label)} tại ${esc(roomLabel(i))}" ${allocation.length<2?'disabled':''}>Đổi phòng</button></div>`).join(''):'<span class="small muted">Không phát sinh phụ thu</span>'}</div>`;}
function transferNotice(){return transferUndo&&JSON.stringify(allocation)===transferUndo.after?`<div class="transfer-notice" role="status"><span>${esc(transferUndo.message)}</span><button class="linkbtn" data-action="undo-transfer">Hoàn tác</button></div>`:'';}
function showTransfer(target=null){
 const p=pendingTransfer;if(!p)return;
 const config=customerConfig(),guests=guestList(search),service=roomServices(allocation,currentBookingSearch(),config,p.source).find(x=>x.guestId===p.guest&&x.kind===p.kind);
 if(!service){pendingTransfer=null;$('#overlay').innerHTML='';toast('Lựa chọn đã thay đổi. Hãy chọn lại dịch vụ.');return;}
 p.target=target;const options=allocation.map((r,i)=>i===p.source?null:transferService(allocation,currentBookingSearch(),config,p.source,i,p.guest,p.kind));
 const result=target===null?null:options[target],deltaText=n=>n===0?'Không đổi tổng tiền':(n>0?'Tăng ':'Giảm ')+money(Math.abs(n));
 const changes=result?.valid?[p.source,p.target].map(i=>{const gs=guests.filter(g=>result.rows[i].guestIds.includes(g.id));return `<div class="transfer-room-result"><b>${esc(roomLabel(i))}</b><span>${gs.filter(g=>g.adult).length} người lớn${gs.some(g=>!g.adult)?' · '+gs.filter(g=>!g.adult).map(g=>'trẻ '+g.age+' tuổi').join(', '):''} · ${result.rows[i].bedIds.length} giường phụ</span><strong>${money(result.quotes[i].total)}</strong><small>${roomServices(result.rows,currentBookingSearch(),config,i).map(x=>esc(x.label)+' · '+money(x.amount)).join('<br>')||'Không phát sinh phụ thu'}</small></div>`;}).join(''):'';
 modal('Chọn phòng nhận '+(p.kind==='bed'?'giường phụ':'phụ thu'),`<p class="small"><b>${esc(service.label)}</b> đang ở ${esc(roomLabel(p.source))}.</p><p class="small muted">Chuyển cả khách sử dụng dịch vụ để giá và sức chứa luôn khớp. Chọn phòng nhận bên dưới.</p><div class="transfer-destinations">${allocation.map((r,i)=>i===p.source?'':`<button class="transfer-destination ${target===i?'selected':''}" data-action="transfer-target" data-target="${i}" aria-pressed="${target===i}" ${!options[i].valid?'disabled':''}><b>${esc(roomLabel(i))}</b><small>${options[i].valid?deltaText(options[i].delta)+' · Tổng đơn '+money(options[i].total):esc(options[i].reason)}</small></button>`).join('')}</div>${result?.valid?`<div class="transfer-preview"><h3>Sau khi chuyển</h3>${changes}<p class="small">${result.exchange?'Đổi chỗ '+esc(guests.find(g=>g.id===result.exchange).label)+' sang '+esc(roomLabel(p.source))+' để giữ đủ sức chứa.':'Chỉ chuyển khách đi kèm dịch vụ; các khách khác giữ nguyên phòng.'}</p><div class="row between"><span>Tổng đơn mới</span><strong>${money(result.total)}</strong></div><p class="small blue">${deltaText(result.delta)}</p></div>`:'<p class="small muted">Phòng không đáp ứng chính sách sẽ hiển thị lý do và không chọn được.</p>'}`,`<button class="btn secondary" data-action="close-modal">Hủy</button><button class="btn" data-action="apply-transfer" ${!result?.valid?'disabled':''}>Áp dụng chuyển</button>`);
 $('#overlay .modal').classList.add('service-modal');
}
function showGuestPriceDetails(id){
 const config=customerConfig(),r=config.rooms.find(r=>r.id===id),check=bookingValidation(),all=guestList(search),days=nights(search);
 if(!r||!allocation.some(row=>row.roomId===id))return;
 const body=allocation.map((row,i)=>row.roomId!==id?'':`<section class="guest-price-room"><div class="row between"><h3>Phòng ${i+1} · ${esc(r.name)}</h3><span class="pill">${row.guestIds.length} khách</span></div><p class="small muted">Gói ${ratePlan(row.ratePlanId).name} · ${days} đêm</p><div class="guest-info-list">${all.filter(g=>row.guestIds.includes(g.id)).map(g=>`<div class="row between"><span>${esc(g.label)}</span><span>${row.bedIds.includes(g.id)?'Giường phụ':'Giường có sẵn'}</span></div>`).join('')}</div><div class="price-lines">${check.quotes[i].lines.map(l=>`<div><span>${esc(l.label)}${days>1?`<small class="auto-unit">${money(l.amount/days)} / đêm × ${days} đêm</small>`:''}</span><span class="nowrap">${money(l.amount)}</span></div>`).join('')}<div class="total"><span>Tổng phòng · ${days} đêm</span><span>${money(check.quotes[i].total)}</span></div></div></section>`).join('');
 modal('Chi tiết khách & giá',body,`<button class="btn" data-action="close-modal">Đóng</button>`);
 $('#overlay .modal').classList.add('service-modal');
}


function customerPolicy(){const config=customerConfig();return `<section class="customer-policy" id="customer-policy"><h3>Các chính sách</h3><p class="small blue">Giá phòng bao gồm cả người lớn và trẻ em trong số khách tiêu chuẩn từng phòng. Mức phụ thu dưới đây chỉ áp dụng cho khách ngoài số tiêu chuẩn.</p><div class="customer-policy-grid"><div><b class="small">Chính sách trẻ em</b><p>${config.allowChildren?'Chấp nhận trẻ em ở mọi độ tuổi.':'Không nhận khách dưới 18 tuổi.'}<br>Dưới ${config.childFreeBelow} tuổi: miễn phụ thu khi dùng giường có sẵn.<br>${config.childFreeBelow}–${childAgeUpper(config)} tuổi: ${money(config.childFee)}/trẻ/đêm.<br>Từ ${config.adultFrom} tuổi: áp dụng cách tính giá người lớn.</p><b class="small">Chính sách khách thêm tính giá người lớn</b><p>${adultSurchargePolicy(config)}</p></div><div><b class="small">Chính sách giường phụ</b><p>${config.extraEnabled?config.rooms.filter(r=>r.bedEnabled).map(r=>`${r.name}: tối đa ${r.beds}, ${money(r.bedPrice)}/giường/đêm`).join('<br>'):'Không cung cấp giường phụ.'}</p><p>${config.bedIncludesGuest?'Giá giường phụ đã bao gồm phụ thu người sử dụng.':'Giá giường phụ chưa bao gồm phụ thu lưu trú.'}<br>Giường phụ ưu tiên cho khách tính giá người lớn vượt tiêu chuẩn. Trẻ dưới mốc giá người lớn dùng giường có sẵn, vẫn tính trong sức chứa và giới hạn trẻ em.</p><b class="small">Nhận phòng 14:00 · Trả phòng 12:00</b></div></div></section>`;}
function checkoutPage(){const v=bookingValidation();if(!allocation.length)return customerShell('<main class="customer-main empty"><h2>Chưa có phòng được chọn</h2><a class="btn" href="#/customer/hotel">Quay lại chọn phòng</a></main>');return customerShell(checkoutContent({allocation,search:currentBookingSearch(),config:customerConfig(),contact,v,error:checkoutError,automatic}));}
function formatDate(d){return new Date(d+'T00:00:00Z').toLocaleDateString('vi-VN',{timeZone:'UTC'});}
function bookingDetail(b){if(b.automatic)return `<div class="row between"><div><b>Awaken Da Nang Hotel</b><p class="small muted">${formatDate(b.search.in)} — ${formatDate(b.search.out)} · ${summary(b.search)}</p></div><h2 class="blue">${money(b.total)}</h2></div>${aggregateRoomsHTML(b.groups,nights(b.search))}<p class="small muted">${automaticNote}</p>`;return `<div class="row between wrap"><div><b>Awaken Da Nang Hotel</b><p class="small muted">${formatDate(b.search.in)} — ${formatDate(b.search.out)} · ${nights(b.search)} đêm<br>${summary(b.search)}</p></div><div class="right"><span class="small muted">Tổng tiền</span><h2 class="blue">${money(b.total)}</h2></div></div>${b.rows.map((row,i)=>`<div class="bordered section-space"><div class="row between wrap"><h3>Phòng ${i+1} · ${row.name}</h3><span class="pill">Đã xác nhận</span></div><p class="small blue">Gói ${ratePlan(row.ratePlanId)?.name||'Tiết kiệm'} · ${ratePlan(row.ratePlanId)?.cancellation||''}</p><p class="small">${row.guests.map(g=>`${esc(g.label)} — ${row.bedIds.includes(g.id)?'Giường phụ':'Dùng giường có sẵn'}`).join('<br>')}</p>${priceLines(row.quote)}</div>`).join('')}`;}
function confirmationPage(){if(!lastBooking)return customerShell('<main class="empty"><h2>Chưa có đặt phòng mô phỏng</h2><a href="#/customer/hotel" class="btn">Chọn phòng</a></main>');return customerShell(`<main class="customer-main"><div class="confirmation"><div class="center"><div class="check-circle">✓</div><h1>Đặt phòng mô phỏng thành công</h1><p class="muted">Mã đặt thử: <b>${lastBooking.id}</b> · ${esc(lastBooking.name)}</p></div><div class="checkout-card">${bookingDetail(lastBooking)}</div><div class="note">${lastBooking.automatic?'Đã ghi nhận số lượng từng loại phòng và phụ thu toàn đơn. Không xác nhận giường phụ, phụ thu hoặc cơ cấu khách thuộc phòng nào.':'Thông tin khách, giường, gói giá và phụ thu đã được lưu theo từng phòng.'} Đây là đơn thử nghiệm, không phải xác nhận của khách sạn.</div><div class="row between section-space"><a class="btn secondary" href="#/extranet/bookings">Xem đơn trong Extranet</a><a href="#/customer/hotel">Quay lại khách sạn</a></div></div></main>`);}
function adminBookings(){return adminShell(lastBooking?`<div class="admin-card"><div class="row between"><h2>Chi tiết đặt phòng · ${lastBooking.id}</h2><span class="pill">Đơn mô phỏng</span></div><p class="small">Người đặt: <b>${esc(lastBooking.name)}</b></p>${bookingDetail(lastBooking)}<div class="note">Chính sách và giá được giữ theo thời điểm đặt thử. Thay đổi Extranet sau đó không tự sửa đơn này.</div></div>`:'<div class="admin-card empty"><h2>Chưa có đơn đặt thử</h2><p class="muted">Chọn phòng, sắp xếp khách và xác nhận trên trang khách hàng để xem đơn tại đây.</p><a class="btn" href="#/customer/hotel">Đến trang khách hàng</a></div>','Đặt phòng');}
function render(keepScroll=false){const y=scrollY;const r=route();let html;if(r.startsWith('/extranet')){html=r.endsWith('/dashboard')?adminDashboard():r.endsWith('/rooms')?adminRooms():r.endsWith('/capacity')?adminCapacity():r.endsWith('/calendar')?adminCalendar():r.endsWith('/bookings')?adminBookings():adminPolicy();}else html=r.endsWith('/home')?homePage():r.endsWith('/results')?resultsPage():r.endsWith('/checkout')?checkoutPage():r.endsWith('/confirmation')?confirmationPage():hotelPage();$('#app').innerHTML=toolbar()+html;if(keepScroll)window.scrollTo(0,y);document.title=(r.startsWith('/extranet')?'Extranet':'Bookese')+' | Phòng, khách & phụ thu';}
function ensureSearch(){if(!Number.isFinite(nights(pendingSearch))||!Number.isInteger(pendingSearch.adults)||pendingSearch.adults<1||pendingSearch.adults>24||pendingSearch.rooms<1||pendingSearch.rooms>6||pendingSearch.children.some(x=>x<0||x>17)||nights(pendingSearch)<1||nights(pendingSearch)>30){toast('Kiểm tra ngày lưu trú (1–30 đêm), người lớn và số phòng (1–6).');return false;}return true;}
function runSearch(target){transferUndo=null;if(!ensureSearch())return;search=clone(pendingSearch);allocation=[];selected=emptySelection();selectedPlan=null;popover=false;const to='/customer/'+target;if(route()===to){render(true);}else nav(to);if(target==='hotel')setTimeout(()=>$('#availability')?.scrollIntoView({block:'start'}),0);}
function chooseRec(index){transferUndo=null;const rec=available()[index];if(!rec)return;selected=clone(rec.counts);selectedPlan=rec.ratePlanId;contact.terms=false;allocation=rec.allocation.map(({roomId,ratePlanId,guestIds,bedIds})=>({roomId,ratePlanId,guestIds,bedIds}));render(true);}

function autoAllocate(){transferUndo=null;if(!Object.values(selected).some(n=>n))selectedPlan=null;const q=currentAutoQuote();allocation=q.valid?q.allocation:[];contact.terms=false;render(true);}

function preset(key){const presets={'five-two':{adults:5,rooms:2,children:[]},'five-one':{adults:5,rooms:1,children:[]},family:{adults:4,rooms:2,children:[5,8]},older:{adults:2,rooms:1,children:[12]},'four-one':{adults:4,rooms:1,children:[]},'two-children':{adults:2,rooms:1,children:[5,8]}};pendingSearch={...search,...presets[key],market:'Đà Nẵng'};$('#overlay').innerHTML='';runSearch('results');}
function rules(){modal('Quy tắc áp dụng trong bản thử nghiệm',`<p>Giao diện giữ bố cục Bookese hiện tại. Các phòng trong một booking phải cùng gói giá (quy tắc Bookese trong prototype). ${automatic?'Phương án tự động: tìm 1 phòng ưu tiên sức chứa sát nhu cầu; tìm nhiều phòng so sánh tổ hợp từ 1 đến số phòng tìm kiếm theo tổng tiền. Khách chỉ chọn loại và số lượng; cơ cấu khách từng phòng không được xác nhận.':'Phương án khách điều chỉnh: cùng cách đề xuất và tính phí như phương án tự động; khách chọn phòng nhận giường phụ hoặc phụ thu bằng nút Đổi phòng trong giới hạn chính sách. Chi tiết khách & giá chỉ hiển thị thông tin.'} Những trường và bước mới được đánh dấu <span class="tag">Mới</span>.</p><table class="rule-table"><tr><th>Quy tắc</th><th>Trong prototype</th></tr><tr><td>Giá người thêm không giường</td><td>Mặc định minh họa <b>150.000đ/người/đêm</b>, có thể sửa trong Extranet. Đây chưa phải giá thật của khách sạn.</td></tr><tr><td>Giường phụ</td><td>200.000đ ở hai loại phòng chính. Mặc định gói đã gồm phụ thu người sử dụng; bỏ chọn nếu khách sạn muốn cộng riêng.</td></tr><tr><td>Giới hạn chỗ ngủ</td><td>Chỗ thêm dùng giường có sẵn = sức chứa tối đa − khách tiêu chuẩn − giường phụ đang bật. Vẫn kiểm tra riêng giới hạn người lớn và trẻ em.</td></tr><tr><td>Ưu tiên giường phụ</td><td>Ưu tiên giường phụ cho khách tính giá người lớn vượt tiêu chuẩn. Trẻ dưới mốc giá người lớn dùng giường có sẵn, không tự thêm giường phụ; chỉ phụ thu theo tuổi khi hết suất tiêu chuẩn.</td></tr><tr><td>Tuổi trẻ em</td><td>Theo mốc tuổi đang lưu: từ tuổi miễn phí đến dưới mốc người lớn. Ví dụ mốc 13 hiển thị cận trên 12.99. Tuổi thực không thay đổi. Mỗi phòng cần 1 người lớn từ 18 tuổi.</td></tr><tr><td>Giá cơ bản</td><td>Bao gồm người lớn và trẻ em trong số khách tiêu chuẩn từng phòng. Chỉ khách vượt tiêu chuẩn mới áp dụng giường phụ hoặc phụ thu theo tuổi.</td></tr><tr><td>Giới hạn dùng giường có sẵn</td><td>Tự tính từ sức chứa, số khách tiêu chuẩn và số giường phụ đang bật; không nhập riêng. Khi tắt giường phụ, tính lại với 0 giường.</td></tr><tr><td>Phạm vi mô phỏng</td><td>Đà Nẵng → Awaken. Giá và inventory mẫu giống nhau mỗi ngày; chưa nối tồn phòng/giường thật, thanh toán, khuyến mãi hay gửi email.</td></tr></table><p class="small muted" style="margin-top:18px">Cấu hình được lưu riêng trong trình duyệt. Đơn đặt thử chỉ tồn tại trong phiên. Các menu ngoài luồng phòng và phụ thu là phần giao diện tham chiếu.</p>`,`<button class="btn" data-action="close-modal">Đã hiểu</button>`);}
function scenarios(){modal('Chọn tình huống để trải nghiệm',`<p class="muted">Awaken từ 700.000đ, alo ha từ 800.000đ, Phòng Gia đình từ 1.500.000đ. Hai gói Tiết kiệm và Linh hoạt. Dùng cấu hình đang được lưu trong Extranet. Sau khi đổi cấu hình, kết quả của các tình huống có thể thay đổi.</p><div class="scenario-grid">${[['five-two','5 người lớn · 2 phòng','So sánh Awaken × 2 và Awaken + alo ha theo gói giá.'],['five-one','5 người lớn · 1 phòng','Phòng Gia đình đủ chỗ cho cả nhóm.'],['family','4 người lớn + trẻ 5, 8 tuổi · 2 phòng','Chuyển từng trẻ và xem phụ thu theo phòng.'],['older','2 người lớn + trẻ 12 tuổi · 1 phòng','Trẻ 12 tuổi áp dụng giá người lớn.'],['four-one','4 người lớn · 1 phòng','alo ha: 1 giường phụ + 1 người thêm không giường.'],['two-children','2 người lớn + 2 trẻ · 1 phòng','Kiểm tra tổng khách và giới hạn trẻ em.']].map(([id,t,d])=>`<button class="scenario" data-action="preset" data-preset="${id}"><strong>${t}</strong><small>${d}</small></button>`).join('')}</div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='set-mode')return changeMode(b.dataset.mode,autoExample?'ab':'saved');if(a==='auto-sample')return changeMode(automatic?'automatic':'manual',b.dataset.sample);if(b.tagName==='A')e.preventDefault();if(a==='move-service'){pendingTransfer={source:Number(b.dataset.source),guest:b.dataset.guest,kind:b.dataset.kind,target:null};showTransfer();return;}if(a==='transfer-target'){showTransfer(Number(b.dataset.target));return;}if(a==='apply-transfer'){const p=pendingTransfer;if(!p||p.target===null)return;const result=transferService(allocation,currentBookingSearch(),customerConfig(),p.source,p.target,p.guest,p.kind);if(!result.valid){toast(result.reason);showTransfer();return;}const before=clone(allocation),destination=roomLabel(p.target),label=p.kind==='bed'?'giường phụ':'khách có phụ thu';allocation=result.rows;transferUndo={before,after:JSON.stringify(allocation),message:'Đã chuyển '+label+' sang '+destination+'. Tổng đơn '+money(result.total)+'.'};contact.terms=false;pendingTransfer=null;$('#overlay').innerHTML='';render(true);$('.transfer-notice')?.scrollIntoView({block:'start',behavior:'smooth'});toast(transferUndo.message);return;}if(a==='undo-transfer'){if(transferUndo&&JSON.stringify(allocation)===transferUndo.after){allocation=transferUndo.before;transferUndo=null;contact.terms=false;render(true);toast('Đã khôi phục bố trí trước khi chuyển.');}return;}if(a==='close-modal'){$('#overlay').innerHTML='';return;}if(a==='scenarios')return scenarios();if(a==='rules')return rules();if(a==='reset'){return modal('Đặt lại dữ liệu thử nghiệm?',`<p>Khôi phục cấu hình và giá minh họa ban đầu, xóa lựa chọn phòng và đơn đặt thử trong phiên này.</p>`,`<button class="btn secondary" data-action="close-modal">Giữ lại</button><button class="btn" data-action="confirm-reset">Đặt lại</button>`);}if(a==='confirm-reset'){config=initialConfig();draft=clone(config);localStorage.setItem(KEY,JSON.stringify(config));configDirty=false;formError='';lastBooking=null;allocation=[];selected=emptySelection();selectedPlan=null;$('#overlay').innerHTML='';pendingSearch={in:'2026-11-10',out:'2026-11-11',adults:5,children:[],rooms:2,market:'Đà Nẵng'};search=clone(pendingSearch);render();toast('Đã khôi phục dữ liệu mẫu.');return;}
 if(a==='save-config'){const errors=configErrors(draft);if(errors.length){formError=errors.join(' ');render();window.scrollTo(0,0);return;}config=clone(draft);localStorage.setItem(KEY,JSON.stringify(config));configDirty=false;formError='';allocation=[];selected=emptySelection();selectedPlan=null;render(true);toast('Đã cập nhật. Trang khách hàng sử dụng cấu hình mới.');return;}
 if(a==='cancel-config'){draft=clone(config);configDirty=false;formError='';render(true);toast('Đã khôi phục cấu hình đang lưu.');return;}
 if(a==='edit-room'){activeRoom=b.dataset.id;nav('/extranet/capacity');return;}
 if(a==='edit-dates'){modal('Ngày nhận & trả phòng',`<div class="checkout-form"><label class="field"><span>Ngày nhận phòng</span><input type="date" value="${pendingSearch.in}" data-search="in" aria-label="Ngày nhận phòng"></label><label class="field"><span>Ngày trả phòng</span><input type="date" value="${pendingSearch.out}" data-search="out" aria-label="Ngày trả phòng"></label></div>`,`<button class="btn" data-action="apply-dates">Áp dụng</button>`);return;}
 if(a==='apply-dates'){if(!ensureSearch())return;$('#overlay').innerHTML='';render(true);return;}
 if(a==='toggle-guests'){popover=!popover;if(popover)guestDraft=clone(pendingSearch);render(true);return;}
 if(a==='counter'){let k=b.dataset.key,n=Number(b.dataset.step);if(k==='children'){if(n>0)guestDraft.children.push(5);else guestDraft.children.pop();}else guestDraft[k]+=n;render(true);return;}
 if(a==='apply-guests'){pendingSearch=clone(guestDraft);popover=false;render(true);return;}
 if(a==='search')return runSearch(b.dataset.target);
 if(a==='preset')return preset(b.dataset.preset);
 if(a==='try-two'){pendingSearch={...search,rooms:2};runSearch(route().endsWith('hotel')?'hotel':'results');return;}
 if(a==='hide-banner'){hideBanner=true;render(true);return;}
 if(a==='choose-rec')return chooseRec(Number(b.dataset.index));
 if(a==='auto-allocate')return autoAllocate();
 if(a==='guest-price-details'){showGuestPriceDetails(b.dataset.id);return;}
 if(a==='switch-plan'){contact.terms=false;selectedPlan=b.dataset.plan;if(automatic){autoAllocate();toast('Đã đổi gói và tự tính lại tổng phụ thu.');return;}const changed=allocation.map(row=>({...row,ratePlanId:selectedPlan}));if(changed.length&&validateBooking(changed,currentBookingSearch(),customerConfig()).valid){allocation=changed;render(true);}else autoAllocate();toast('Đã đổi tất cả phòng đã chọn sang gói '+ratePlan(selectedPlan).name+'. Tổng giá đã cập nhật.');return;}
 if(a==='scroll-allocation'){$('#availability')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(a==='scroll-rooms'){$('#availability')?.scrollIntoView({behavior:'smooth'});return;}
 if(a==='scroll-policy'){$('#customer-policy')?.scrollIntoView({behavior:'smooth'});return;}
 if(a==='edit-allocation'){nav('/customer/hotel');setTimeout(()=>$('#availability')?.scrollIntoView({block:'start'}),50);return;}
 if(a==='checkout'){const v=bookingValidation();if(!v.valid){toast('Vui lòng sửa phân bổ trước khi tiếp tục.');return;}checkoutError='';nav('/customer/checkout');return;}
 if(a==='checkout-voucher'){const feedback=$('#voucher-feedback');feedback.textContent=contact.voucher?.trim()?'Chưa hỗ trợ áp dụng voucher trong bản thử nghiệm. Tổng tiền giữ nguyên.':'Vui lòng nhập mã voucher.';return;}

 if(a==='price-policy'||a==='room-details'){const config=customerConfig();const r=config.rooms.find(r=>r.id===b.dataset.id);modal(r.name,`<img src="assets/room.jpg" alt="Phòng nghỉ" style="width:100%;max-height:230px;border-radius:6px"><div class="section-space"><b>Giá cơ bản ${money(r.price)}/đêm · tối đa ${r.base} khách, gồm người lớn và trẻ em</b><p>Tổng tối đa ${r.max} khách; không quá ${r.adults} người lớn và ${r.children} trẻ em.</p><p>Giường có sẵn đáp ứng tối đa ${r.base+existingExtraPlaces(r,config)} khách tính giá người lớn; trẻ dưới mốc giá người lớn được ngủ chung trong giới hạn tổng khách và trẻ em của phòng. Giường phụ tối đa ${roomBeds(r,config)}.</p><p>Người lớn thêm dùng giường có sẵn: ${money(config.adultFee)}/đêm.<br>Giường phụ: ${money(r.bedPrice)}/giường/đêm ${config.bedIncludesGuest?'(đã gồm phụ thu người sử dụng)':'(chưa gồm phụ thu lưu trú)'}.</p><p class="muted small">Giá cuối được tính theo khách và giường được chọn cho từng phòng.</p></div>`,`<button class="btn" data-action="close-modal">Đóng</button>`);return;}
 if(a==='hotel-info'){modal('Awaken Da Nang Hotel',`<p>10 Chemin de Montpellier, Đà Nẵng</p><p>Khách sạn 5 sao · Điểm đánh giá 7,8/10</p><p>Wifi miễn phí · Nhà hàng · Hồ bơi · Spa & chăm sóc sức khỏe · Lễ tân 24/24</p><p class="muted small">Prototype tập trung vào phòng, khách và phụ thu. Bạn có thể xem thông tin chi tiết trên trang Bookese gốc.</p>`,`<button class="btn" data-action="close-modal">Đóng</button>`);}
});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.config){let k=el.dataset.config;draft[k]=el.type==='checkbox'?el.checked:el.type==='radio'?el.value==='true':el.type==='number'?Number(el.value):el.value;configDirty=true;render(true);return;}if(el.dataset.room){let r=draft.rooms.find(r=>r.id===el.dataset.room);r[el.dataset.field]=el.type==='checkbox'?el.checked:Number(el.value);configDirty=true;render(true);return;}if(el.dataset.search){pendingSearch[el.dataset.search]=el.value;return;}if(el.dataset.childAge!==undefined){guestDraft.children[Number(el.dataset.childAge)]=Number(el.value);return;}if(el.dataset.quantity){if(selectedPlan&&selectedPlan!==el.dataset.plan&&Object.values(selected).some(n=>n>0)){toast('Các phòng phải cùng gói giá. Hãy dùng nút Đổi cả đơn.');render(true);return;}selectedPlan=el.dataset.plan;selected[el.dataset.quantity]=Number(el.value);autoAllocate();return;}if(el.id==='active-room'){activeRoom=el.value;render(true);return;}if(el.id==='calendar-start'){calendarStart=el.value;render(true);return;}if(el.id==='calendar-room'){$$('[data-calendar-id]').forEach(row=>row.hidden=el.value!=='all'&&row.dataset.calendarId!==el.value);return;}});
document.addEventListener('input',e=>{const el=e.target;if(el.type==='number'&&(el.dataset.config||el.dataset.room)){if(el.dataset.config)draft[el.dataset.config]=Number(el.value);else draft.rooms.find(r=>r.id===el.dataset.room)[el.dataset.field]=Number(el.value);configDirty=true;const selector=el.dataset.config?'[data-config="'+el.dataset.config+'"]':'[data-room="'+el.dataset.room+'"][data-field="'+el.dataset.field+'"]';render(true);$(selector)?.focus({preventScroll:true});return;}if(e.target.dataset.search)pendingSearch[e.target.dataset.search]=e.target.value;if(e.target.id==='contact-name')contact.name=e.target.value;if(e.target.id==='contact-email')contact.email=e.target.value;});

document.addEventListener('submit',e=>{
 if(e.target.id!=='booking-form')return;e.preventDefault();
 const form=e.target;let invalid=[...form.querySelectorAll('input,select,textarea')].find(el=>!el.checkValidity());
 if(!contact.name?.trim())invalid=$('#contact-name');
 if(invalid){const panel=invalid.closest('details');if(panel)panel.open=true;invalid.focus();invalid.reportValidity();checkoutError='Vui lòng điền đầy đủ thông tin liên hệ hợp lệ.';$('#checkout-error').textContent=checkoutError;return;}
 const v=bookingValidation();
 if(!contact.terms||!v.valid){checkoutError=!contact.terms?'Vui lòng xác nhận điều khoản trước khi đặt thử.':v.errors.join(' ');$('#checkout-error').textContent=checkoutError;return;}
 const gs=guestList(search);lastBooking={id:'DEMO-'+Date.now().toString().slice(-6),name:contact.name.trim(),contact:{...clone(contact),payment:allocation[0].ratePlanId==='flex'?'property':contact.payment||'card',myself:contact.myself!==false,vat:contact.vat||'no'},automatic,groups:automatic?automaticSummary(allocation,currentBookingSearch(),customerConfig()):null,requestedRooms:search.rooms,search:clone(currentBookingSearch()),total:v.total,policy:clone(customerConfig()),rows:allocation.map((row,i)=>({name:customerConfig().rooms.find(r=>r.id===row.roomId).name,ratePlanId:row.ratePlanId,guests:gs.filter(g=>row.guestIds.includes(g.id)),bedIds:[...row.bedIds],quote:clone(v.quotes[i])}))};nav('/customer/confirmation');
});
function updateCheckoutContact(el){
 const key=el.dataset.contact;if(!key)return;
 contact[key]=el.type==='checkbox'?el.checked:el.value;
 if(key==='terms')$('#booking-submit').disabled=!contact.terms||!bookingValidation().valid;
 if(key==='myself'){const wrap=$('#guest-name-field');wrap.hidden=contact.myself;wrap.querySelector('input').required=!contact.myself;}
 if(key==='vat'){const wrap=$('#invoice-fields');wrap.hidden=contact.vat!=='yes';wrap.querySelectorAll('input').forEach(input=>input.required=contact.vat==='yes');}
}
document.addEventListener('input',e=>updateCheckoutContact(e.target));
document.addEventListener('change',e=>updateCheckoutContact(e.target));

document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#overlay').innerHTML='';if(popover){popover=false;render(true);}}if(e.key==='Tab'&&$('#overlay .modal')){const focusable=[...$('#overlay .modal').querySelectorAll('button,a,input,select')].filter(x=>!x.disabled);let first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{popover=false;formError='';render();window.scrollTo(0,0);});
window.addEventListener('storage',e=>{if(e.key===KEY){try{config=normalizeConfig(JSON.parse(e.newValue));draft=clone(config);allocation=[];selected=emptySelection();selectedPlan=null;render(true);toast('Đã đồng bộ cấu hình từ tab Extranet.');}catch{}}});
render();
